# Barkeep recipe set. Written for this project; ingredient ratios of classic drinks
# are common bar knowledge, all texts are our own. Released under CC0.
#
# R(id, name, type, styles, glass, method, color, flavors, ings, garnish, about, season, servings, name_de)
# ings: (key, amount, unit[, flag])  unit: ml dash tsp bsp pc slice sprig leaf g pinch top
# flag: 'm' = muddle, 't' = top up, 'f' = float, 'r' = rinse

def R(id, name, type, styles, glass, method, color, flavors, ings, garnish=None, about=None,
      season=(), servings=1, name_de=None, difficulty=1, extra=None):
    return dict(id=id, name=name, type=type, styles=list(styles), glass=glass, method=method, color=color,
                flavors=list(flavors), ings=ings, garnish=garnish, about=about, season=list(season),
                servings=servings, name_de=name_de, difficulty=difficulty, extra=extra)

